#![deny(clippy::all, clippy::pedantic)]
#![deny(missing_docs)]
#![deny(unsafe_code)]

//! Literal-stream search implementation.

/// Represents the starting byte offset of a detected needle match.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LiteralMatch {
    /// The absolute zero-indexed position in the concatenated stream.
    pub offset: u64,
}

/// Results of a literal search operation.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LiteralSearchResult {
    /// A list of match offsets found (up to `max_matches`).
    pub matches: Vec<LiteralMatch>,
    /// True if more matches exist beyond the returned list.
    pub truncated: bool,
    /// Total number of bytes processed from all input chunks.
    pub bytes_scanned: u64,
}

/// Errors that can occur during a literal search.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LiteralSearchError {
    /// The provided needle was empty.
    EmptyNeedle,
    /// The limit for matches requested was zero.
    ZeroMatchLimit,
    /// The total byte count exceeded the capacity of `u64`.
    OffsetOverflow,
}

/// Searches for a `needle` in a stream of `chunks` provided by an iterator.
///
/// This function identifies all occurrences (including overlapping ones) of the needle
/// across chunk boundaries without joining chunks into a single buffer, maintaining
/// memory usage bounded by `O(needle.len() + max_matches)`.
///
/// # Errors
///
/// Returns [`LiteralSearchError::EmptyNeedle`] if `needle` is empty.
/// Returns [`LiteralSearchError::ZeroMatchLimit`] if `max_matches` is zero.
/// Returns [`LiteralSearchError::OffsetOverflow`] if the total stream size exceeds `u64::MAX`.
#[must_use]
pub fn search_literal_chunks<'a, I>(
    chunks: I,
    needle: &'a [u8],
    max_matches: usize,
) -> Result<LiteralSearchResult, LiteralSearchError>
where
    I: IntoIterator<Item = &'a [u8]>,
{
    if needle.is_empty() {
        return Err(LiteralSearchError::EmptyNeedle);
    }
    if max_matches == 0 {
        return Err(LiteralSearchError::ZeroMatchLimit);
    }

    let mut matches = Vec::with_capacity(max_matches.min(1024));
    let mut bytes_scanned: u64 = 0;
    let mut truncated = false;
    let needle_len = needle.len();

    // The overlap buffer stores the suffix of the stream needed to detect matches 
    // that start in the current chunk but end in a future chunk.
    // A match starting at index `i` needs bytes up to `i + needle_len - 1`.
    // Thus, we need the last `needle_len - 1` bytes of the previously seen stream.
    let mut overlap_buffer: Vec<u8> = Vec::with_capacity(needle_len.saturating_sub(1));

    for chunk in chunks {
        let chunk_len = chunk.len() as u64;

        // Calculate the total stream length including this chunk.
        if let Some(next_total) = bytes_scanned.checked_add(chunk_len) {
            bytes_scanned = next_total;
        } else {
            return Err(LiteralSearchError::OffsetOverflow);
        }

        // Create a logical view: [overlap_buffer] + [chunk]
        // We only search for matches that *start* within the current chunk or 
        // at indices covered by the overlap buffer but not fully processed.

        // To handle overlapping matches and boundary conditions correctly, we look for all 
        // occurrences in the sequence `[overlap_buffer + chunk]` that start at an index 
        // belonging to either the previous context or this new chunk.

        let mut combined_view = overlap_buffer.clone();
        combined_view.extend_from_slice(chunk);

        // The first byte in `combined_view` is at absolute offset: (bytes_scanned - chunk_len) - overlap_buffer.len()
        // But it's easier to track the current stream pointer.
        let base_offset = bytes_scanned.saturating_sub(chunk_len).saturating_sub(overlap_buffer.len() as u64);

